static pearl_state state={.ready=true,.track=0,.volume=30,.seconds=83};
pearl_state pearl_audio_state(void){return state;}
void pearl_audio_play(int n){state.track=n;state.paused=false;}
void pearl_library_rescan(void){}
void pearl_audio_play_collection(int collection,int position){state.track=lib->collections[collection].tracks[position];state.paused=false;}
void pearl_audio_toggle(void){state.paused=!state.paused;}
void pearl_audio_step(int d){state.track=pearl_next(lib,state.track,d);}
static uint8_t framebuffer[460*460*3];
static void flush(lv_disp_drv_t *d,const lv_area_t *a,lv_color_t *pixels){for(int y=a->y1;y<=a->y2;y++)for(int x=a->x1;x<=a->x2;x++){lv_color32_t c={.full=lv_color_to32(*pixels++)};if(x>=0&&x<460&&y>=0&&y<460){size_t i=(y*460+x)*3;framebuffer[i]=c.ch.red;framebuffer[i+1]=c.ch.green;framebuffer[i+2]=c.ch.blue;}}lv_disp_flush_ready(d);}
static void work(void){tick(NULL);art_request request;while(xQueueReceive(art_requests,&request,0)){art_result result={load_art(&request),request.generation,request.slot};assert(xQueueSend(art_results,&result,0));}tick(NULL);}
static lv_indev_data_t touch;
static void read_touch(lv_indev_drv_t *drv,lv_indev_data_t *data){*data=touch;}
static void frame(int x,int y,bool pressed){touch.point.x=x;touch.point.y=y;touch.state=pressed?LV_INDEV_STATE_PR:LV_INDEV_STATE_REL;lv_tick_inc(40);lv_timer_handler();}
static void tap(int x,int y){frame(x,y,true);frame(x,y,false);frame(x,y,false);}
static void swipe(int x1,int y1,int x2,int y2){frame(x1,y1,true);for(int i=1;i<=5;i++)frame(x1+(x2-x1)*i/5,y1+(y2-y1)*i/5,true);frame(x2,y2,false);frame(x2,y2,false);}
static void capture(const char *path){work();lv_refr_now(NULL);FILE *f=fopen(path,"wb");assert(f);fprintf(f,"P6\n460 460\n255\n");fwrite(framebuffer,1,sizeof(framebuffer),f);fclose(f);}
